def solve(nums):
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n
    for i in range(n):
        for k in range(i):
            if nums[k] < nums[i]:
                dp[i] = max(dp[i], dp[k] + 1)
    return max(dp)
