def solve(haystack, needle):
    len_haystack = len(haystack)
    len_needle = len(needle)

    if len_needle > len_haystack:
        return -1

    # Precompute the bad character last occurrence
    bad_char = {}
    for i, char in enumerate(needle):
        bad_char[char] = i

    i = 0
    while i <= len_haystack - len_needle:
        j = len_needle - 1
        while j >= 0 and haystack[i + j] == needle[j]:
            j -= 1
        if j < 0:
            return i
        # Move the window based on the bad character
        i += max(1, j - bad_char.get(haystack[i + j], -1))

    return -1
