    len_hay = len(haystack)
    len_nee = len(needle)

    if len_nee > len_hay:
        return -1

    # Precompute the bad character table for the KMP algorithm
    def build_bad_char_table(pattern):
        table = {}
        length = len(pattern)
        for i in range(length):
            table[pattern[i]] = i
        return table

    # KMP algorithm
    def kmp_search(text, pattern, bad_char_table):
        len_text = len(text)
        len_pattern = len(pattern)
        i = 0  # index for text
        j = 0  # index for pattern
