def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Precompute the bad character last occurrence for each character
    def build_last_occurrence(pattern):
        last = {}
        for i, char in enumerate(pattern):
            last[char] = i
        return last

    last_occurrence = build_last_occurrence(needle)

    # KMP algorithm
    i = 0  # index for haystack
    j = 0  # index for needle

    while i < len_h:
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == len_n:
                return i - len_n
        else:
            if j != 0:
                j = last_occurrence[needle[j - 1]]
            else:
                i += 1
    return -1
```

