def solve(haystack, needle):
    len_hay = len(haystack)
    len_need = len(needle)

    if len_need > len_hay:
        return -1

    # Preprocess needle to create a list of character positions
    # This is a simple helper for KMP algorithm
    def build_lps(pattern):
        lps = [0] * len(pattern)
        length = 0  # Length of the previous longest prefix suffix

        for i in range(1, len(pattern)):
            while length > 0 and pattern[i] != pattern[length]:
                length = lps[length - 1]
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
            else:
                lps[i] = 0
        return lps

    # KMP algorithm
    lps = build_lps(needle)
    i = j = 0  # i for haystack, j for needle

    while i < len_hay:
        if needle[j] == haystack[i]:
            i += 1
            j += 1
        if j == len_need:
            return i - j
        elif i < len_hay and needle[j] != haystack[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return -1
```

