def solve(haystack, needle):
    len_hay = len(haystack)
    len_need = len(needle)

    if len_need > len_hay:
        return -1

    # Precompute the prefix function for KMP algorithm
    def compute_prefix(pattern):
        m = len(pattern)
        pi = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                pi[i] = j
            else:
                pi[i] = 0
        return pi

    prefix = compute_prefix(needle)

    j = 0  # Index for needle
    for i in range(len_hay):
        while j > 0 and haystack[i] != needle[j]:
            j = prefix[j - 1]
        if haystack[i] == needle[j]:
            j += 1
        if j == len_need:
            return i - len_need + 1
    return -1
