def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Preprocess the needle for efficient pattern matching
    # Using KMP algorithm to avoid naive sliding window
    lps = [0] * len_n
    length = 0  # length of the previous longest prefix suffix

    for i in range(1, len_n):
        while length > 0 and needle[i] != needle[length]:
            length = lps[length - 1]
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
        else:
            lps[i] = 0

    # Now search for the pattern in the text using KMP
    length = 0  # index into needle
    for i in range(len_h):
        while length > 0 and haystack[i] != needle[length]:
            length = lps[length - 1]
        if haystack[i] == needle[length]:
            length += 1
        if length == len_n:
            return i - len_n + 1
    return -1
```

