    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Using KMP algorithm for efficient substring search
    # Preprocess the needle to create the longest prefix suffix (LPS) array
    lps = [0] * len_n
    length = 0  # length of the previous longest prefix suffix

    for i in range(1, len_n):
        while length > 0 and needle[i] != needle[length]:
            length = lps[length - 1]
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
        else:
            lps[i] = 0

    # Search for the pattern in the haystack
    i = j = 0
    while i < len_h:
        while j > 0 and haystack[i] != needle[j]:
            j = lps[j - 1]
        if haystack[i] == needle[j]:
            i += 1
            j += 1
        if j == len_n:
            return i - j
    return -1
```

