def solve(haystack, needle):
    len_hay = len(haystack)
    len_nee = len(needle)

    if len_nee > len_hay:
        return -1

    # Precompute the bad character last occurrence for each character
    bad_char = {}
    for i, char in enumerate(needle):
        bad_char[char] = i

    index = 0
    while index <= len_hay - len_nee:
        # Find the mismatch position
        j = len_nee - 1
        while j >= 0 and haystack[index + j] == needle[j]:
            j -= 1
        if j == -1:
            return index
        # Shift the window
        shift = j - bad_char.get(haystack[index + j], -1)
        index += max(1, shift)

    return -1
