    def bfs(start):
        visited = set()
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(visited)

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited_nodes = set()
    components = 0

    for node in range(n):
        if node not in visited_nodes:
            components += 1
            visited_nodes.update(bfs(node))

    return components
```

