def solve(n, edges):
    # Initialize a list to keep track of visited nodes
    visited = [False] * n

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # DFS to mark all reachable nodes from a given node
    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    # Count connected components
    components = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            components += 1

    return components
```

