def solve(n, edges):
    # Initialize a list to keep track of visited nodes
    visited = [False] * n

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # DFS to mark all nodes in the same component as visited
    def dfs(node):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    # Count the number of connected components
    components = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            components += 1

    return components
```

