def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals based on their start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    # Use a priority queue (min-heap) to keep track of the end times of selected intervals
    import heapq
    heap = []
    for interval in sorted_intervals:
        start, end = interval
        if not heap or start >= heap[0]:
            heapq.heappush(heap, end)
        else:
            # Replace the interval with the current one if it overlaps less
            heapq.heappop(heap)
            heapq.heappush(heap, end)

    return len(intervals) - len(heap)
```

