def solve(intervals):
    if not intervals:
        return []

    # Find the maximum end value to determine the size of the array
    max_end = max(end for start, end in intervals)

    # Initialize a list to keep track of merged intervals
    merged = []

    # Create a list to represent the intervals on a timeline
    timeline = [False] * (max_end + 1)

    # Mark the start and end of each interval on the timeline
    for start, end in intervals:
        timeline[start] = True
        timeline[end] = False

    # Traverse the timeline to merge overlapping intervals
    current_start = -1
    for i in range(len(timeline)):
        if timeline[i]:
            if current_start == -1:
                current_start = i
        else:
            if current_start != -1:
                merged.append([current_start, i])
                current_start = -1

    # Handle the case where the last interval is not closed
    if current_start != -1:
        merged.append([current_start, len(timeline) - 1])

    return merged
