def solve(intervals):
    if not intervals:
        return []

    # Find the maximum end value to determine the size of the array
    max_end = max(end for start, end in intervals)
    # Initialize a list to track which intervals are covered
    covered = [False] * (max_end + 1)

    # Mark the covered positions
    for start, end in intervals:
        for i in range(start, end + 1):
            covered[i] = True

    # Merge the covered intervals
    merged = []
    current_start = 0
    for i in range(max_end + 1):
        if covered[i]:
            if current_start == 0:
                current_start = i
        else:
            if current_start != 0:
                merged.append([current_start, i - 1])
                current_start = 0
    # Add the last interval if there is one
    if current_start != 0:
        merged.append([current_start, max_end])

    return merged
