        return []

    # Find the maximum end value to determine the size of the array
    max_end = max(end for start, end in intervals)

    # Initialize a list to track which intervals are merged
    merged = [False] * len(intervals)

    # Mark intervals that are already merged
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if intervals[i][1] >= intervals[j][0]:
                merged[j] = True

    # Collect non-merged intervals
    result = []
    for i in range(len(intervals)):
        if not merged[i]:
            result.append(intervals[i])

    # Sort the result by start value
    result.sort()

    # Merge overlapping intervals
    merged_result = []
    for interval in result:
        if not merged_result or merged_result[-1][1] < interval[0]:
            merged_result.append(interval)
        else:
            merged_result[-1][1] = max(merged_result[-1][1], interval[1])

    return merged_result
