def solve(intervals):
    if not intervals:
        return []

    # Find the maximum end value to determine the range
    max_end = max(end for start, end in intervals)

    # Initialize a list to track merged intervals
    merged = []

    # Create a list of all start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by position, and by type ('start' comes before 'end' at the same position)
    points.sort(key=lambda x: (x[0], 0 if x[1] == 'start' else 1))

    # Track current interval
    current_start = None
    current_end = None

    for pos, typ in points:
        if typ == 'start':
            if current_start is None:
                current_start = pos
            else:
                # If we encounter a start before the current end, it's part of the same interval
                if pos <= current_end:
                    current_end = max(current_end, pos)
                else:
                    merged.append([current_start, current_end])
                    current_start = pos
                    current_end = pos
        else:
            if current_start is not None:
                if pos >= current_end:
                    merged.append([current_start, current_end])
                    current_start = None
                    current_end = None
                else:
                    current_end = max(current_end, pos)

    if current_start is not None:
        merged.append([current_start, current_end])

    return merged
