def solve(intervals):
    if not intervals:
        return []

    # Create a list of start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by value, and by type (start comes before end if same value)
    points.sort(key=lambda x: (x[0], x[1] == 'start'))

    merged = []
    current_start = None
    current_end = None

    for point, typ in points:
        if typ == 'start':
            if current_start is None:
                current_start = point
            else:
                # Overlapping or touching, extend current_end
                current_end = max(current_end, point)
        else:
            if current_start is not None:
                # End of interval
                merged.append([current_start, current_end])
                current_start = None
                current_end = None

    return merged
