def solve(intervals):
    if not intervals:
        return []

    # Find the minimum start and maximum end to define the range
    min_start = min(interval[0] for interval in intervals)
    max_end = max(interval[1] for interval in intervals)

    # Create a set to track merged intervals
    merged = set()

    # Mark all points in the range as covered
    covered = [False] * (max_end + 1)

    for start, end in intervals:
        for i in range(start, end + 1):
            covered[i] = True

    # Now find all merged intervals by checking contiguous covered points
    result = []
    current_start = -1
    for i in range(min_start, max_end + 1):
        if covered[i]:
            if current_start == -1:
                current_start = i
        else:
            if current_start != -1:
                result.append([current_start, i - 1])
                current_start = -1
    if current_start != -1:
        result.append([current_start, max_end])

    return result
