from collections import Counter

def solve(nums, k):
    count = Counter(nums)
    frequencies = list(count.values())
    max_freq = max(frequencies)
    most_common = [num for num, freq in count.items() if freq == max_freq]
    if k == 1:
        return most_common
    freq_list = []
    for num, freq in count.items():
        if freq < max_freq:
            freq_list.append((freq, num))
    freq_list.sort(reverse=True)
    selected = []
    for freq, num in freq_list:
        if len(selected) < k - 1:
            selected.append(num)
    return most_common + selected
```

