def solve(nums):
    n = len(nums)
    if n == 0:
        return 0

    # Initialize an array to store the length of the longest increasing subsequence ending at each index
    dp = [1] * n

    # For each element, check all previous elements to update dp[i]
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
