        if low == high:
            return arr[low]
        pivot_idx = partition(arr, low, high)
        if k == pivot_idx:
            return arr[pivot_idx]
        elif k < pivot_idx:
            return quickselect(arr, low, pivot_idx - 1, k)
        else:
            return quickselect(arr, pivot_idx + 1, high, k)

    return quickselect(nums, 0, len(nums) - 1, k)
