def solve(intervals):
    if not intervals:
        return []

    # Create a frequency array to count the number of intervals covering each point
    max_end = max(end for start, end in intervals)
    freq = [0] * (max_end + 2)  # Extra space to handle end points

    for start, end in intervals:
        freq[start] += 1
        freq[end + 1] -= 1

    merged = []
    current_start = 0
    current_count = 0

    for i in range(len(freq)):
        if current_count == 0 and freq[i] > 0:
            current_start = i
            current_count = freq[i]
        elif current_count > 0:
            current_count += freq[i]
        else:
            current_count += freq[i]

        if current_count == 0 and i != 0:
            merged.append([current_start, i - 1])

    return merged
