def solve(intervals):
    if not intervals:
        return []

    # Create a frequency array to count overlaps
    max_val = max(end for start, end in intervals)
    freq = [0] * (max_val + 1)

    # Mark start and end points
    for start, end in intervals:
        freq[start] += 1
        freq[end + 1] -= 1

    # Calculate prefix sum to find merged intervals
    merged = []
    current_start = None
    current_count = 0

    for i in range(len(freq)):
        current_count += freq[i]
        if current_count > 0:
            if current_start is None:
                current_start = i
        else:
            if current_start is not None:
                merged.append([current_start, i - 1])
                current_start = None

    return merged
```

