        if len(arr) == 1:
            return arr[0]
        pivot_index = partition(arr, 0, len(arr) - 1)
        if k == pivot_index + 1:
            return arr[pivot_index]
        elif k < pivot_index + 1:
            return quickselect(arr[:pivot_index], k)
        else:
            return quickselect(arr[pivot_index+1:], k - (pivot_index + 1))

    return quickselect(nums.copy(), k)
