def solve(nums, k):
    nums_count = {}
    for num in nums:
        nums_count[num] = nums_count.get(num, 0) + 1

    sorted_nums = sorted(nums_count.keys())
    for num in sorted_nums:
        if k <= nums_count[num]:
            return num
        k -= nums_count[num]
    return -1
