def solve(nums):
    for i in range(len(nums)):
        current = nums[i]
        while nums[current - 1] != current:
            next_val = nums[current - 1]
            nums[current - 1] = nums[next_val - 1]
            nums[current - 1], nums[next_val - 1] = nums[next_val - 1], current
            current = next_val
    for num in nums:
        if nums[num - 1] != num:
            return num
    return -1
