def solve(intervals):
    if not intervals:
        return []

    # Create a list of start and end points
    start_end = [(interval[0], interval[1]) for interval in intervals]

    # Find the minimum start and maximum end to determine the range
    min_start = min(s for s, e in start_end)
    max_end = max(e for s, e in start_end)

    # Initialize a merged list
    merged = []
    current_start = min_start
    current_end = min_start - 1

    # Iterate through all possible points from min_start to max_end
    for point in range(min_start, max_end + 1):
        # Check if the point is the start of any interval
        for s, e in start_end:
            if s == point:
                if current_end < s:
                    # No overlap, add the current merged interval
                    if current_start <= current_end:
                        merged.append([current_start, current_end])
                    current_start = s
                    current_end = e
                else:
                    # Overlapping, extend the current interval
                    current_end = max(current_end, e)
        # Check if the point is the end of any interval
        for s, e in start_end:
            if e == point:
                if current_end < e:
                    # No overlap, add the current merged interval
                    if current_start <= current_end:
                        merged.append([current_start, current_end])
                    current_start = s
                    current_end = e
                else:
                    # Overlapping, extend the current interval
                    current_end = max(current_end, e)

    # Add the last merged interval
    if current_start <= current_end:
        merged.append([current_start, current_end])

    return merged
