def solve(intervals):
    if not intervals:
        return []

    # Create a list of all start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by value, and for same values, end comes before start
    points.sort(key=lambda x: (x[0], x[1] == 'end'))

    merged = []
    current_start, current_end = None, None
    in_interval = False

    for point, typ in points:
        if typ == 'start':
            if not in_interval:
                current_start = point
                in_interval = True
            else:
                # Overlapping interval, extend current_end if needed
                current_end = max(current_end, point)
        else:
            if in_interval:
                current_end = point
                in_interval = False
                merged.append([current_start, current_end])

    return merged
