def solve(intervals):
    if not intervals:
        return []

    # Find the minimum start and maximum end to create a range
    min_start = min(interval[0] for interval in intervals)
    max_end = max(interval[1] for interval in intervals)

    # Create a set to track covered points
    covered = set()

    # Mark all points covered by intervals
    for start, end in intervals:
        for point in range(start, end + 1):
            covered.add(point)

    # Build merged intervals
    merged = []
    current_start = min_start
    for point in range(min_start, max_end + 1):
        if point in covered:
            if not merged or merged[-1][1] < point:
                merged.append([point, point])
        else:
            if merged and merged[-1][1] == point - 1:
                merged[-1][1] = point
            elif merged and merged[-1][1] < point:
                merged.append([point, point])

    # Convert merged points back to intervals
    result = []
    for i in range(0, len(merged), 1):
        if i == 0 or merged[i][0] > merged[i-1][1] + 1:
            result.append([merged[i][0], merged[i][1]])

    return result
