    for start in range(min_start, max_end + 1):
        for end in range(start, max_end + 1):
            # Check if there is at least one interval that covers [start, end]
            has_interval = False
            for interval in intervals:
                if interval[0] <= start and interval[1] >= end:
                    has_interval = True
                    break
            if has_interval:
                current_end = max(current_end, end)
            else:
                if current_end >= current_start:
                    merged.append([current_start, current_end])
                current_start = start
                current_end = start

