import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm is not used, but we can use Bellman-Ford instead
    # Bellman-Ford can handle negative weights (but not negative cycles)
    # Since weights are 0 <= w <= 100, no negative cycles are possible

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
