    if not intervals:
        return 0

    # Sort intervals by their end times
    intervals.sort(key=lambda x: x[1])

    removed = 0
    prev_end = -float('inf')

    for start, end in intervals:
        if start < prev_end:
            removed += 1
        else:
            prev_end = end

    return removed
