def solve(n, edges):
    # Initialize adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    components = 0

    for node in range(n):
        if not visited[node]:
            components += 1
            # BFS to mark all nodes in this component
            queue = [node]
            visited[node] = True
            while queue:
                current = queue.pop(0)
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

    return components
```

