def solve(intervals):
    if not intervals:
        return []

    # Create a list to hold the merged intervals
    merged = []

    # Create a list of start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by their value, and by type (start comes before end if same value)
    points.sort(key=lambda x: (x[0], 0 if x[1] == 'start' else 1))

    # Traverse through the points to merge intervals
    current_start = None
    for point, typ in points:
        if typ == 'start':
            if current_start is None:
                current_start = point
        else:
            if current_start is not None:
                merged.append([current_start, point])
                current_start = None

    return merged
