def solve(intervals):
    if not intervals:
        return []

    # Create a list to hold the merged intervals
    merged = []

    # Create a list of start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by their position, and for the same position, 'end' comes before 'start'
    points.sort(key=lambda x: (x[0], x[1] == 'start'))

    # Iterate through the sorted points
    current_start = None
    current_end = None
    for point, typ in points:
        if typ == 'start':
            if current_start is None:
                current_start = point
            else:
                # If the current interval is already open, check if this start is within the current interval
                if point <= current_end:
                    # Overlapping, extend the current interval
                    current_end = max(current_end, point)
                else:
                    # No overlap, close the current interval and start a new one
                    merged.append([current_start, current_end])
                    current_start = point
        else:
            if current_start is not None:
                # If the current interval is open, check if this end is within the current interval
                if point >= current_start and point <= current_end:
                    # Update the end if necessary
                    current_end = max(current_end, point)
                else:
                    # Close the current interval
                    merged.append([current_start, current_end])
                    current_start = None
                    current_end = None

    # Add the last interval if it's still open
    if current_start is not None:
        merged.append([current_start, current_end])

    return merged
