def solve(intervals):
    if not intervals:
        return []

    # Create a list of all start and end points
    points = []
    for start, end in intervals:
        points.append((start, 1))  # Start of an interval
        points.append((end, -1))   # End of an interval

    # Sort points by their value, and by type (start before end if same value)
    points.sort(key=lambda x: (x[0], x[1]))

    merged = []
    current_start = None
    current_end = None

    for point, typ in points:
        if typ == 1:
            if current_start is None:
                current_start = point
            else:
                # If we are at a start point and we already have a current start,
                # it means there's a gap, so finalize the current interval
                if current_end < point:
                    merged.append([current_start, current_end])
                    current_start = point
                else:
                    # Overlapping, extend the current interval
                    current_end = max(current_end, point)
        else:
            # End point
            if current_start is not None:
                # If we are at an end point and have a current start,
                # check if it's the end of the current interval
                if current_end == point:
                    merged.append([current_start, current_end])
                    current_start = None
                    current_end = None
                else:
                    # Not the end, keep current interval open
                    current_end = point

    # Add the last interval if any
    if current_start is not None:
        merged.append([current_start, current_end])

    return merged
