def solve(intervals):
    if not intervals:
        return []

    # Find the minimum start and maximum end to define the range
    min_start = min(i[0] for i in intervals)
    max_end = max(i[1] for i in intervals)

    # Create a set to mark covered points
    covered = set()

    # Mark all points covered by intervals
    for start, end in intervals:
        for i in range(start, end + 1):
            covered.add(i)

    # Build merged intervals from covered points
    merged = []
    current_start = min_start
    for i in range(min_start, max_end + 1):
        if i in covered:
            current_end = i
        else:
            if current_start <= current_end:
                merged.append([current_start, current_end])
            current_start = i + 1
    if current_start <= current_end:
        merged.append([current_start, current_end])

    return merged
