def solve(intervals):
    if not intervals:
        return []

    # Find the minimum start and maximum end to define the range
    min_start = min(interval[0] for interval in intervals)
    max_end = max(interval[1] for interval in intervals)

    # Initialize a list to track if a point is covered
    covered = [False] * (max_end + 1)

    # Mark all points covered by intervals
    for start, end in intervals:
        for i in range(start, end + 1):
            covered[i] = True

    # Merge intervals by checking consecutive covered points
    merged = []
    current_start = -1
    for i in range(min_start, max_end + 1):
        if covered[i]:
            if current_start == -1:
                current_start = i
        else:
            if current_start != -1:
                merged.append([current_start, i - 1])
                current_start = -1
    if current_start != -1:
        merged.append([current_start, max_end])

    return merged
